    def is_valid(r, c):
        return 0 <= r < len(grid) and 0 <= c < len(grid[0]) and grid[r][c] == '.'

    def neighbors(r, c):
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            if is_valid(r + dr, c + dc):
                yield r + dr, c + dc

    if not is_valid(*start) or not is_valid(*goal):
